// Draft generated by FreeLLMAPI (dots-3-note-preview); reviewed by Claude.
const express = require('express');
const { authenticate } = require('../middleware/auth');
const { authLimiter } = require('../middleware/rateLimit');
const c = require('../controllers/accountController');

const router = express.Router();
router.use(authenticate);

router.get('/sessions', c.sessions);
router.delete('/sessions/:familyId', c.revokeSession);
router.patch('/email', authLimiter, c.changeEmail);
router.post('/deactivate', authLimiter, c.deactivate);
router.post('/delete', authLimiter, c.deleteAccount);

module.exports = router;
